from common import *
import traceback
if __name__=='__main__':
    save_source(__file__)
    # Wait only on this known training/inference pipeline process. Never launch training from this monitor.
    pid=int(sys.argv[1])
    while True:
        try:os.kill(pid,0)
        except ProcessLookupError:break
        time.sleep(15)
    for v in VARIANTS:
        if not (BASE/'metrics'/f'{v}.json').is_file():
            print('Training or inference requires attention before conditional evaluation:',v,flush=True);sys.exit(2)
    for n in ['strategy','finalize']:
        with (BASE/'docs'/f'{n}.log').open('a') as f:
            subprocess.run([sys.executable,str(TMP/f'{n}.py')],cwd=ROOT,stdout=f,stderr=subprocess.STDOUT,check=True)
